<?php
namespace Tests\Feature; use Tests\TestCase; use Illuminate\Foundation\Testing\RefreshDatabase; use App\Models\{User,Role,ProviderCategory}; use Illuminate\Support\Facades\Hash; use Illuminate\Support\Str;
class ProviderTest extends TestCase { use RefreshDatabase; private function user(string $role='REGISTERED_USER'){ $u=User::create(['name'=>'Test','phone'=>'+201'.random_int(100000000,999999999),'password_hash'=>Hash::make('Password1'),'status'=>'ACTIVE']);$u->roles()->attach(Role::firstOrCreate(['name'=>$role]));return $u;} protected function setUp():void{parent::setUp();$this->artisan('migrate');foreach(['REGISTERED_USER','PROVIDER','ADMIN','SUPER_ADMIN'] as $r)Role::firstOrCreate(['name'=>$r]);ProviderCategory::create(['name'=>'Trainer','status'=>'ACTIVE']);}
 public function test_user_can_apply():void{$u=$this->user();$this->actingAs($u,'api')->postJson('/api/v1/provider-applications',['category_id'=>1,'bio'=>'Experienced','experience_years'=>5,'phone'=>$u->phone,'location'=>'Cairo'])->assertCreated();}
 public function test_duplicate_pending_application_blocked():void{$u=$this->user();$d=['category_id'=>1,'bio'=>'Experienced','phone'=>$u->phone,'location'=>'Cairo'];$this->actingAs($u,'api')->postJson('/api/v1/provider-applications',$d)->assertCreated();$this->actingAs($u,'api')->postJson('/api/v1/provider-applications',$d)->assertStatus(422);}
 public function test_admin_approval_creates_provider_and_role():void{$u=$this->user();$admin=$this->user('ADMIN');$a=$this->actingAs($u,'api')->postJson('/api/v1/provider-applications',['category_id'=>1,'bio'=>'Experienced','phone'=>$u->phone,'location'=>'Cairo'])->json('data.id');$this->actingAs($admin,'api')->postJson("/api/v1/admin/provider-applications/$a/approve")->assertOk();$this->assertDatabaseHas('providers',['user_id'=>$u->id]);$this->assertTrue($u->fresh()->roles()->where('name','PROVIDER')->exists());}
 public function test_public_directory_only_verified():void{$this->getJson('/api/v1/providers')->assertOk();}
}
